// Presentation layer inspired by the supplied fsbmaj.ru reference.
// The content below remains grounded in the owner's documents.
export function renderReferenceHeader({path,icon,account}) {
 const nav=[['about','О службе'],['tasks','Задачи'],['structure','Структура'],['documents','Документы'],['ranks','Звания'],['gallery','Галерея']];
 return `<div class="header-inner ref-header-inner"><a href="#/" class="brand" aria-label="ФСБ — Россия Онлайн, главная"><img class="brand-mark" src="assets/emblem.svg?v=applications-1" width="32" height="38" alt=""><span class="brand-text"><span class="brand-name">ФСБ</span><span class="brand-sub">РОССИЯ ОНЛАЙН</span></span></a><nav class="main-nav ref-nav" aria-label="Основная навигация">${nav.map(([id,label])=>`<a class="nav-link" href="#/?section=${id}">${label}</a>`).join('')}<a class="nav-link ${path==='/applications/transfer'?'active':''}" href="#/applications/transfer">Переводы</a><a class="nav-link ${path.startsWith('/applications')&&path!=='/applications/transfer'?'active':''}" href="#/applications">Заявки</a></nav><div class="ref-header-actions"><button class="header-search icon-button" data-action="open-search" aria-label="Поиск по порталу">${icon('search',19)}</button><a class="button secondary ref-staff-link portal-account-link" href="#/account">${account?.profile?'Мой аккаунт':'Войти'} ${icon('arrow',17)}</a><button class="menu-toggle icon-button" data-action="menu" aria-expanded="false" aria-controls="mobile-menu" aria-label="Открыть меню">${icon('menu')}</button></div></div><nav class="mobile-menu" id="mobile-menu" aria-label="Мобильная навигация" hidden>${nav.map(([id,label])=>`<a href="#/?section=${id}">${label} ${icon('arrow',18)}</a>`).join('')}<a href="#/applications/transfer">Переводы в ФСБ ${icon('arrow',18)}</a><a href="#/applications">Заявки ${icon('arrow',18)}</a><a href="#/account">${account?.profile?'Мой аккаунт':'Войти'} ${icon('arrow',18)}</a><a href="#/staff">Сотрудникам ${icon('arrow',18)}</a><a href="#/newcomer">Новичку ${icon('arrow',18)}</a></nav>`;
}

const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function star(cx,cy,r=7){let points=[];for(let i=0;i<10;i++){const a=(-90+i*36)*Math.PI/180;const radius=i%2?r*.43:r;points.push(`${cx+Math.cos(a)*radius},${cy+Math.sin(a)*radius}`);}return `<polygon points="${points.join(' ')}" fill="#c8b57b"/>`;}
let insigniaId=0;
export function epaulet(rank){ const patternId='insignia-'+(++insigniaId);
 const general=rank.includes('Генерал'); const junior=['Старшина','Прапорщик','Сержант','Младший Сержант'].includes(rank);
 let marks='';
 const count=rank==='Генерал'?4:rank.includes('Генерал-Полковник')?3:rank.includes('Генерал-Лейтенант')?2:rank.includes('Генерал-Майор')?1:rank==='Полковник'?3:rank==='Подполковник'?2:rank==='Майор'?1:rank==='Капитан'?4:rank==='Старший Лейтенант'?3:rank==='Лейтенант'?2:rank==='Младший Лейтенант'?1:rank==='Прапорщик'?2:0;
 if(count){const size=general?10:junior?5:7;const positions=count===1?[[36,69]]:count===2?[[36,56],[36,84]]:count===3?[[36,47],[36,71],[36,95]]:[[24,62],[48,62],[36,87],[36,106]];marks=positions.map(([x,y])=>star(x,y,size)).join('');}
 else{const stripes=rank==='Старшина'?1:rank==='Сержант'?3:2;marks=Array.from({length:stripes},(_,i)=>`<path d="m19 ${57+i*12} 17 9 17-9" fill="none" stroke="#c8b57b" stroke-width="${rank==='Старшина'?9:4}"/>`).join('');}
 return `<svg viewBox="0 0 72 156" role="img" aria-label="Стилизованный погон: ${e(rank)}"><defs><pattern id="${patternId}" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 0h4M0 2h4" stroke="#cbb679" stroke-opacity=".07"/></pattern></defs><path d="M7 151V24L36 5l29 19v127Z" fill="${general?'#423b25':'#18211f'}" stroke="#b59d5c" stroke-width="1.2"/><path d="M12 146V27l24-16 24 16v119Z" fill="url(#${patternId})" stroke="#b59d5c" stroke-opacity=".4"/><path d="M7 151V24L36 5l29 19v127" fill="none" stroke="#d81f2a" stroke-opacity=".7" stroke-width="2"/>${!general&&!junior?'<path d="M27 24v119m18-119v119" stroke="#a72c32" stroke-width="3" opacity=".75"/>':''}<circle cx="36" cy="28" r="4" fill="#c8b57b"/>${marks}<path d="M17 135h38" stroke="#b59d5c" stroke-opacity=".4"/></svg>`;
}

function sectionLabel(n,label){return `<div class="ref-section-label"><span>${n} / ${label}</span><i></i></div>`;}
export function renderReferenceHome({departments,ranks,icon,sourceLink,documentCards}){
 const arrow=()=>icon('arrow',18);
 const groups=[...new Set(ranks.map(r=>r[0]))];
 const taskData=[['shield','Внутренний контроль','Соблюдение законодательства, дисциплина и противодействие коррупции.','m'],['book','Кадры и подготовка','Приём на службу, обучение, аттестации и профессиональный рост.','ukp'],['network','Организованная преступность','Работа по ОПГ, контрразведка и информационная безопасность.','ubpo'],['target','Специальные операции','Силовое сопровождение, антитеррор и освобождение заложников.','alpha'],['compass','Особые задачи','Противодействие контрабанде и обеспечение безопасности при ЧП и ВП.','vympel'],['academy','Подготовка курсантов','Курс молодого бойца, экзамены и стажировки в управлениях.','academy']];
 return `<section class="ref-hero" id="top"><div class="ref-scene" id="hero-scene"><canvas id="emblem-canvas" aria-hidden="true"></canvas><div class="scene-fallback"><img src="assets/emblem.svg?v=applications-1" width="260" height="290" alt="Эмблема игровой фракции ФСБ · Россия Онлайн"></div></div><div class="ref-hero-vignette"></div><div class="container ref-hero-content"><p class="ref-kicker"><i></i> ГОСУДАРСТВЕННАЯ БЕЗОПАСНОСТЬ · РОССИЯ ОНЛАЙН</p><h1 class="ref-word" aria-label="ФСБ"><span class="ref-letter" aria-hidden="true">Ф</span><span class="ref-letter" aria-hidden="true">С</span><span class="ref-letter" aria-hidden="true">Б</span></h1><h2 class="ref-subtitle">Федеральная служба<br>безопасности</h2><p class="ref-lead">Информационный портал игровой фракции.<br>Структура, документы и знания для уверенной службы.</p><div class="ref-actions"><a class="button primary" href="#/staff">Справочник сотрудника ${arrow()}</a><a class="button secondary" href="#/?section=about">О службе ${arrow()}</a></div><p class="ref-note">ОТКРЫТЫЕ МАТЕРИАЛЫ · GTA 5 RP · РОССИЯ ОНЛАЙН</p></div><div class="container ref-hero-bottom"><div class="ref-status"><i></i><span>ПОРТАЛ</span><b>СОТРУДНИКОВ</b></div><div class="ref-status"><i></i><span>ОСНОВАНИЕ</span><b>УСТАВ И ЗАКОН</b></div><div class="ref-status"><i></i><span>ПРИНЦИП</span><b>ДИСЦИПЛИНА</b></div><a href="#/?section=about" class="ref-scroll">ЛИСТАТЬ ВНИЗ <span>↓</span></a></div></section>

 <section class="ref-stats container" aria-label="Материалы портала">${[[5,'управлений','СТРУКТУРА СЛУЖБЫ'],[10,'глав устава','НОРМАТИВНАЯ БАЗА'],[18,'статей закона','ПРАВА И ОБЯЗАННОСТИ'],[2,'уровня учреждения','НАВИГАЦИЯ ПО ЗДАНИЮ']].map(([n,label,meta])=>`<div class="ref-stat ref-reveal"><span class="ref-stat-value" data-count="${n}">${n}</span><span class="ref-stat-label">${label}</span><span class="ref-stat-meta">${meta}</span></div>`).join('')}</section>

 <section class="container ref-section" id="about">${sectionLabel('01','О СЛУЖБЕ')}<div class="ref-section-head ref-reveal"><h2>Служба начинается<br>с понимания своей<br><em>ответственности.</em></h2></div><div class="ref-about"><div class="ref-about-visual ref-reveal"><div class="ref-about-orbit"></div><img src="assets/emblem.svg?v=applications-1" width="210" height="240" alt="Эмблема игровой фракции ФСБ · Россия Онлайн"><span>СИМВОЛ СЛУЖБЫ · ИГРОВОЙ ПОРТАЛ</span></div><div class="ref-about-copy ref-reveal"><p>Федеральная служба безопасности проекта «Россия Онлайн» объединяет управления с разными задачами: от подготовки курсантов и внутреннего контроля до специальных операций.</p><p>Здесь собраны материалы, которые помогают сотруднику ориентироваться в правилах: полный устав, игровой федеральный закон, положение управления «М», форма «Альфы» и схемы учреждения.</p><div class="ref-values">${[['01','Законность','Полномочия действуют в установленных границах. Основания и ограничения — в документах.'],['02','Дисциплина','Субординация, служебный порядок и ответственность за свои действия.'],['03','Подготовка','Знание правил, обучение и слаженная работа своего управления.']].map(([n,title,text])=>`<div><span>${n}</span><h3>${title}</h3><p>${text}</p></div>`).join('')}</div>${sourceLink('II.5.13','Обязанности сотрудника · полный текст')}</div></div></section>

 <section class="container ref-section" id="tasks">${sectionLabel('02','ДЕЯТЕЛЬНОСТЬ')}<div class="ref-section-head ref-reveal"><h2>Направления<br>деятельности</h2><p>Специализация каждого управления — по предоставленному уставу. Общие правила службы действуют для всех сотрудников.</p></div><div class="ref-tasks-grid">${taskData.map(([i,title,text,id],n)=>`<a class="ref-task ref-reveal" href="#/departments/${id}"><div class="ref-task-top"><span>0${n+1}</span>${icon(i,26)}</div><h3>${title}</h3><p>${text}</p><span class="ref-task-arrow">${arrow()}</span></a>`).join('')}</div></section>

 <section class="container ref-section" id="structure">${sectionLabel('03','СТРУКТУРА')}<div class="ref-section-head ref-reveal"><h2>Структура<br>службы</h2><p>Пять управлений и Академия внутри УКП. У каждого — своя задача, компетенция и ответственность.</p></div><div class="ref-structure-grid">${departments.map(d=>`<article class="ref-structure-card ref-reveal"><span class="ref-dept-code">${d.id==='academy'?'ПОДОТДЕЛ УКП':'УПРАВЛЕНИЕ'} / ${e(d.code)}</span><h3 class="ref-dept-name">${e(d.name)}${['alpha','vympel'].includes(d.id)?` <small>${d.id==='alpha'?'Альфа':'Вымпел'}</small>`:''}</h3><p class="ref-dept-description">${e(d.description)}</p><ul class="ref-dept-tasks">${d.tasks.slice(0,3).map(t=>`<li>${e(t)}</li>`).join('')}</ul><a class="ref-dept-link" href="#/departments/${d.id}">Обязанности и документы ${arrow()}</a></article>`).join('')}</div></section>

 <section class="container ref-section" id="documents">${sectionLabel('04','ДОКУМЕНТЫ')}<div class="ref-docs-layout"><div class="ref-access-visual ref-reveal"><div class="ref-access-card"><div class="ref-access-top"><span>ФСБ / РОССИЯ ОНЛАЙН</span><i></i></div><div class="ref-access-mark"><img src="assets/emblem.svg?v=applications-1" width="80" height="90" alt=""></div><div class="ref-access-chip"></div><span class="ref-access-title">ИНФОРМАЦИОННЫЙ<br>ПОРТАЛ СОТРУДНИКА</span><div class="ref-access-lines"><i></i><i></i><i></i><i></i><i></i></div><div class="ref-access-bottom"><span>УСТАВ · ПОРЯДОК · СЛУЖБА</span><b>РО</b></div></div><span class="ref-access-caption">ДОКУМЕНТЫ, КОТОРЫЕ ВСЕГДА ПОД РУКОЙ</span></div><div class="ref-docs-copy ref-reveal"><h2>Основание<br>каждого<br>решения</h2><p>Полные документы с удобным чтением и поиском. Краткие памятки связаны с исходными нормами: можно сразу перейти к нужному пункту.</p><div class="ref-doc-list"><a href="#/documents/charter"><span><b>Устав ФСБ</b><small>10 глав · структура, обязанности и дисциплина</small></span>${arrow()}</a><a href="#/documents/law"><span><b>Федеральный закон «О ФСБ»</b><small>4 главы · 18 статей · игровой документ РО</small></span>${arrow()}</a><a href="#/documents/regulation-m"><span><b>Положение управления «М»</b><small>Задачи, собственная безопасность и взаимодействие</small></span>${arrow()}</a></div><button class="button primary" data-action="open-search">Найти нужную норму ${icon('search',18)}</button></div></div></section>

 <section class="container ref-section" id="ranks">${sectionLabel('05','ИЕРАРХИЯ')}<div class="ref-section-head ref-reveal"><h2>Должности<br>и знаки различия</h2><p>Иерархия по главе II устава. Погоны — стилизованная иллюстрация; полномочия определяются документами.</p></div><div class="ref-rank-groups">${groups.map(group=>`<div class="ref-rank-group"><h3 class="ref-reveal">${group}</h3><div class="ref-rank-grid">${ranks.filter(r=>r[0]===group).map(([,role,rank])=>`<article class="ref-rank-card ref-reveal"><div class="ref-rank-insignia">${epaulet(rank)}</div><div><h4 class="ref-rank-name">${e(rank)}</h4><p class="ref-rank-role">${e(role)}</p><span class="ref-rank-category">${group}</span></div></article>`).join('')}</div></div>`).join('')}</div><a class="button secondary ref-reveal" href="#/staff?tab=hierarchy">Полная иерархия и подчинённость ${arrow()}</a></section>

 <section class="container ref-section" id="gallery">${sectionLabel('06','МАТЕРИАЛЫ')}<div class="ref-section-head ref-reveal"><h2>Служба<br>в деталях</h2><p>Атмосфера игрового мира и предоставленные материалы. Справочные изображения доступны в полном размере.</p></div><div class="ref-gallery-grid">${[['hero.webp','Атмосфера службы','Созданная для портала игровая иллюстрация'],['academy.webp','Подготовка сотрудников','Атмосферная иллюстрация учебного пространства'],['alpha-uniform.png','Форма управления «А»','Оригинал владельца · два комплекта «Альфы»']].map(([src,title,caption],i)=>`<button class="ref-gallery-item ref-reveal" data-action="lightbox" data-src="assets/${src}" data-caption="${e(title+' — '+caption)}"><div class="ref-gallery-image"><img src="assets/${src}" alt="${e(title)}" loading="lazy"><span>0${i+1}</span><i>${icon('search',24)}</i></div><span class="ref-gallery-caption"><b>${title}</b><small>${caption}</small></span></button>`).join('')}</div><div class="ref-material-links ref-reveal"><a class="text-link" href="#/uniform">Форма и экипировка ${arrow()}</a><a class="text-link" href="#/building">Схема учреждения ${arrow()}</a></div></section>

 <section class="container ref-section" id="academy">${sectionLabel('07','ПОДГОТОВКА')}<div class="ref-section-head ref-reveal"><h2>Путь в службу —<br>через подготовку</h2><p>Академия — подотдел УКП. Основные этапы обучения приведены по описанию в уставе.</p></div><div class="ref-join-layout"><ol class="ref-steps">${[['Курс молодого бойца','Первичная подготовка курсантов в рядах организации.'],['Лекции','Изучение материалов и основ служебной деятельности.'],['Экзамены','Теоретическая и практическая проверка знаний.'],['Стажировка','После прохождения двух курсов — направление в управления.']].map(([title,text],i)=>`<li class="ref-step ref-reveal"><span>0${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol><div class="ref-candidate-panel ref-reveal"><span class="ref-kicker">НАЧАЛО СЛУЖБЫ</span><h3>Сначала —<br>знать правила.</h3><p>Устав, субординация, структура и форма — всё необходимое для первого знакомства со службой.</p><a class="button primary" href="#/newcomer">Путеводитель новичка ${arrow()}</a><p class="ref-note">Условия поступления и контакты ожидают данных владельца.</p></div></div></section>

 <section class="container ref-section ref-faq" id="faq">${sectionLabel('08','ВОПРОСЫ')}<div class="ref-faq-layout"><h2 class="ref-reveal">Частые<br>вопросы</h2><div class="faq ref-reveal"><details><summary>Где посмотреть обязанности своего управления?</summary><p>Выберите подразделение в разделе «Структура». На отдельной странице собраны задачи, ограничения и связанные документы.</p><a href="#/departments">Все управления ↗</a></details><details><summary>Академия — отдельное управление?</summary><p>Академия ФСБ является подотделом УКП. В портале для неё выделена собственная страница для удобства курсантов.</p></details><details><summary>Где найти форму «Альфы»?</summary><p>В разделе «Форма и экипировка»: два комплекта, порядок сборки и допустимые изменения. Редакция материала — от 26.09.2026.</p><a href="#/uniform">Открыть форму ↗</a></details><details><summary>Можно ли искать по полному тексту документов?</summary><p>Да. Поиск находит абзацы устава, закона и положения «М» и ведёт прямо к нужной норме.</p><button class="text-link" data-action="open-search">Открыть поиск ↗</button></details><details><summary>Нужен ли аккаунт для разделов портала?</summary><p>Информационные страницы открыты без регистрации. Для подачи заявки нужны аккаунт на сайте и привязанный Discord.</p></details></div></div></section>

 <section class="container ref-section ref-cta ref-reveal"><img src="assets/emblem.svg?v=applications-1" width="42" height="48" alt=""><h2>Уверенная служба<br>начинается со знаний.</h2><p>Найдите нужную информацию.<br>Действуйте в рамках своих полномочий.</p><div class="ref-actions"><a class="button primary" href="#/staff">Сотрудникам ${arrow()}</a><a class="button secondary" href="#/documents">Документы ${arrow()}</a></div></section>`;
}
